import XCTest
@testable import FmdServerCore
import Crypto
import Foundation

/// Cross-implementation vectors generated by the python fmd_api reference
/// (argon2-cffi + cryptography) — Fixtures/vectors.json. Byte-for-byte
/// agreement proves the Swift port implements the same protocol v2.
struct Vectors: Decodable {
    let username, saltHex, kAuthHex, kPmkHex, masterKeyHex, encMasterKeyHex: String
    let kekCommandHex, kekLocationHex, kekPictureHex: String
    let itemIdHex: String
    let unixMillis: Int64
    let ciphertextCommandHex, plaintextCommand: String
    let ciphertextLocationHex, plaintextLocation: String

    enum CodingKeys: String, CodingKey {
        case username
        case saltHex = "salt_hex"
        case kAuthHex = "k_auth_hex"
        case kPmkHex = "k_pmk_hex"
        case masterKeyHex = "master_key_hex"
        case encMasterKeyHex = "enc_master_key_hex"
        case kekCommandHex = "kek_command_hex"
        case kekLocationHex = "kek_location_hex"
        case kekPictureHex = "kek_picture_hex"
        case itemIdHex = "item_id_hex"
        case unixMillis = "unix_millis"
        case ciphertextCommandHex = "ciphertext_command_hex"
        case plaintextCommand = "plaintext_command"
        case ciphertextLocationHex = "ciphertext_location_hex"
        case plaintextLocation = "plaintext_location"
    }

    static let shared: Vectors = {
        let url = Bundle.module.url(forResource: "vectors", withExtension: "json", subdirectory: "Fixtures")!
        return try! JSONDecoder().decode(Vectors.self, from: Data(contentsOf: url))
    }()
}

func keyBytes(_ k: SymmetricKey) -> String {
    k.withUnsafeBytes { Data($0).hexEncoded }
}

final class ProtocolV2Tests: XCTestCase {

    let v = Vectors.shared

    func testGoldenPasswordKeyDerivation() throws {
        // Argon2id + HKDF must reproduce K_auth / K_pmk exactly.
        let keys = try ProtocolV2.derivePasswordKeys(
            username: v.username,
            password: "correct horse battery staple",
            salt: Data(hexEncoded: v.saltHex)!
        )
        XCTAssertEqual(keyBytes(keys.authKey), v.kAuthHex)
        XCTAssertEqual(keyBytes(keys.preMasterKey), v.kPmkHex)
    }

    func testGoldenMasterKeyUnwrap() throws {
        let mk = try ProtocolV2.decryptMasterKey(
            username: v.username,
            preMasterKey: SymmetricKey(data: Data(hexEncoded: v.kPmkHex)!),
            encryptedMasterKey: Data(hexEncoded: v.encMasterKeyHex)!
        )
        XCTAssertEqual(keyBytes(mk), v.masterKeyHex)
    }

    func testGoldenKEKs() throws {
        let ltk = try LongTermKeys(
            username: v.username,
            masterKey: SymmetricKey(data: Data(hexEncoded: v.masterKeyHex)!)
        )
        XCTAssertEqual(keyBytes(try ltk.kek(.command)), v.kekCommandHex)
        XCTAssertEqual(keyBytes(try ltk.kek(.location)), v.kekLocationHex)
        XCTAssertEqual(keyBytes(try ltk.kek(.picture)), v.kekPictureHex)
    }

    func testGoldenCommandEnvelopeDecrypt() throws {
        let ltk = try LongTermKeys(
            username: v.username,
            masterKey: SymmetricKey(data: Data(hexEncoded: v.masterKeyHex)!)
        )
        let item = FmdEncryptedItem(
            itemID: Data(hexEncoded: v.itemIdHex)!,
            unixMillis: v.unixMillis,
            ciphertext: Data(hexEncoded: v.ciphertextCommandHex)!
        )
        let plain = try ltk.decrypt(item, type: .command)
        XCTAssertEqual(String(data: plain, encoding: .utf8), v.plaintextCommand)
    }

    func testGoldenLocationEnvelopeDecrypt() throws {
        let ltk = try LongTermKeys(
            username: v.username,
            masterKey: SymmetricKey(data: Data(hexEncoded: v.masterKeyHex)!)
        )
        let item = FmdEncryptedItem(
            itemID: Data(hexEncoded: v.itemIdHex)!,
            unixMillis: v.unixMillis,
            ciphertext: Data(hexEncoded: v.ciphertextLocationHex)!
        )
        let plain = try ltk.decrypt(item, type: .location)
        XCTAssertEqual(String(data: plain, encoding: .utf8), v.plaintextLocation)
        let loc = try FmdLocation(jsonData: plain)
        XCTAssertEqual(loc.lat, 51.1, accuracy: 0.0001)
        XCTAssertEqual(loc.lon, 7.2, accuracy: 0.0001)
        XCTAssertEqual(loc.battery ?? -1, 88.0, accuracy: 0.01)
        XCTAssertEqual(loc.provider, "fused")
    }

    func testRoundTripAllTypes() throws {
        let ltk = try LongTermKeys(
            username: v.username,
            masterKey: SymmetricKey(data: Data(hexEncoded: v.masterKeyHex)!)
        )
        let payload = Data("round trip payload — ünïcödé ✓".utf8)
        for type in FmdDataType.allCases {
            let item = try ltk.encrypt(payload, type: type)
            XCTAssertEqual(item.itemID.count, 16)
            let back = try ltk.decrypt(item, type: type)
            XCTAssertEqual(back, payload)
        }
    }

    func testTamperedCiphertextThrows() throws {
        let ltk = try LongTermKeys(
            username: v.username,
            masterKey: SymmetricKey(data: Data(hexEncoded: v.masterKeyHex)!)
        )
        var ct = Data(hexEncoded: v.ciphertextCommandHex)!
        ct[ct.count - 1] ^= 0xFF  // flip a tag bit
        let item = FmdEncryptedItem(
            itemID: Data(hexEncoded: v.itemIdHex)!,
            unixMillis: v.unixMillis,
            ciphertext: ct
        )
        XCTAssertThrowsError(try ltk.decrypt(item, type: .command))
    }

    func testWrongTypeThrows() throws {
        // Decrypting a command envelope with the location KEK must fail (AD + key).
        let ltk = try LongTermKeys(
            username: v.username,
            masterKey: SymmetricKey(data: Data(hexEncoded: v.masterKeyHex)!)
        )
        let item = FmdEncryptedItem(
            itemID: Data(hexEncoded: v.itemIdHex)!,
            unixMillis: v.unixMillis,
            ciphertext: Data(hexEncoded: v.ciphertextCommandHex)!
        )
        XCTAssertThrowsError(try ltk.decrypt(item, type: .location))
    }
}

final class CommandAndModelTests: XCTestCase {

    func testCommandVocabulary() {
        XCTAssertEqual(FmdCommand.ring, "ring")
        XCTAssertEqual(FmdCommand.LocationProvider.gps.rawValue, "locate gps")
        XCTAssertEqual(FmdCommand.LocationProvider.all.rawValue, "locate")
        XCTAssertEqual(FmdCommand.LocationProvider.last.rawValue, "locate last")
        XCTAssertEqual(FmdCommand.Camera.front.rawValue, "camera front")
        XCTAssertEqual(FmdCommand.RingerMode.silent.rawValue, "ringermode silent")
        XCTAssertEqual(FmdCommand.bluetooth(true), "bluetooth on")
        XCTAssertEqual(FmdCommand.doNotDisturb(false), "nodisturb off")
    }

    func testLockSanitization() {
        XCTAssertEqual(FmdCommand.lock(), "lock")
        XCTAssertEqual(FmdCommand.lock(message: nil), "lock")
        XCTAssertEqual(FmdCommand.lock(message: "   "), "lock")
        XCTAssertEqual(FmdCommand.lock(message: "Lost.\nCall 555"), "lock Lost. Call 555")
        XCTAssertEqual(FmdCommand.lock(message: "say \"hi\"  twice"), "lock say hi twice")
    }

    func testLocationLenientParsing() throws {
        let good = Data(#"{"lat":-33.86,"lon":151.2,"date":1700000000000,"accuracy":"junk","bat":42}"#.utf8)
        let loc = try FmdLocation(jsonData: good)
        XCTAssertNil(loc.accuracy)   // unusable optional → nil, fix survives
        XCTAssertEqual(loc.battery ?? 0, 42, accuracy: 0.01)
        XCTAssertThrowsError(try FmdLocation(jsonData: Data(#"{"lat":91.0,"lon":0,"date":1}"#.utf8)))
        XCTAssertThrowsError(try FmdLocation(jsonData: Data("not json".utf8)))
    }

    func testBase64Unpadded() {
        // Unpadded forms occur for 1- and 2-byte inputs ("AA"←"AA==", "AAA"←"AAA=")
        XCTAssertEqual(Base64.decodePadded("AAA"), Base64.decodePadded("AAA="))
        XCTAssertEqual(Base64.decodePadded("AA")?.count, 1)
        XCTAssertEqual(Base64.decodePadded("AAAA")?.count, 3)
        XCTAssertNotNil(Base64.decodePadded("AA"))
    }
}
